-- ============================================================================
-- 서수원JLS 신입생 안내 페이지 — 시험탭 06번 '어디에 붙이나요' 실제 사진 5장 추가
-- CHESS 2장(단어·CHAT) + ACE 3장(T-map·절대수능맵·활용독해) 캐러셀로. 배치는 사진 없던 말 코멘트 자리에.
-- 1.조회 → 2.백업 → 3.적용 → 4.검증 순서. 맨 아래 되돌리기 SQL 있음.
-- ============================================================================

-- 1. 조회 (지금 모습)
select branch_id, length(content_html) from branch_guides where branch_id = 'seosuwonjls';

-- 2. 백업 (이 결과를 복사해 두세요 — 문제 생기면 되돌리기 SQL에 붙여넣으세요)
select content_html from branch_guides where branch_id = 'seosuwonjls';

-- 3. 적용
update branch_guides set content_html = '<div class="g-flow" data-tab="parent"><svg class="g-flow-deco" width="26" height="26" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 1v22M1 12h22M4.2 4.2l15.6 15.6M19.8 4.2 4.2 19.8" stroke="#fff" stroke-width="2.2" stroke-linecap="round"></path></svg><h2><span style="font-family:''Jua'',sans-serif"><span style="font-size:28px">학부모님 한눈에 보기</span></span></h2><ul class="chips"><li><b>회원가입·자녀 등록</b></li><li><b>수강료 결제</b></li><li><b>반교재 구매</b></li><li><b>Q앱 설치</b></li><li><b>옐로우버스 설치</b></li></ul></div><div class="g-sketchwrap" data-tab="parent"><div class="g-grouphead"><span class="g-group">홈페이지에서 할 일</span><a href="https://www.gojls.com" target="_blank" rel="noopener">www.gojls.com ↗</a></div><div class="g-sec"><h2><span class="n">01</span>회원가입 · 자녀 등록</h2><p>정상어학원 홈페이지에서 학부모 회원가입 후 자녀 등록을 진행해 주세요.</p><ol class="g-steps"><li><strong>정상어학원 홈페이지 접속</strong></li><li><strong>학부모 아이디 또는 카카오로 가입</strong><img class="g-img" src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/parent-step-69.png" alt="통합회원 가입 화면"></li><li><strong>회원가입 완료 후 ''자녀 등록하기'' 클릭</strong><img class="g-img" src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/parent-step-70.png" alt="학부모 회원가입 완료 후 자녀 등록하기 버튼"></li><li><strong>자녀 정보 입력 후 ''자녀 추가(회원가입)''</strong><small>아이디·비밀번호, 이름, 생년월일, 학년, 학교를 입력합니다. 학부모와 동일한 정보는 체크박스로 바로 불러올 수 있어요.</small><img class="g-img" src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/parent-step-72.png" alt="자녀 관리 → 자녀추가 입력 화면"></li></ol><div class="g-note"><b>학생 아이디와 비밀번호는 꼭 기억해 주세요</b>온라인 과제를 할 때 학생이 직접 로그인하는 계정이에요. 너무 복잡하게 만들기보다 학생이 기억하기 쉼운 형태로 정해주세요.</div></div></div><div class="g-sec" data-tab="parent"><h2><span class="n">02</span>수강료 결제</h2><p>홈페이지 메인 화면의 아이콘에서 <b>교육비결제</b>를 누르면 돼요.</p><img class="g-img" src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/parent-step-73.png" alt="홈페이지 메인 아이콘 — MY JLS·교육비결제·알림장·MY TREE·상담·반교재"><ol class="g-steps"><li><strong>학부모 아이디로 로그인</strong></li><li><strong>메인 화면에서 ''교육비결제'' 선택</strong></li><li><strong>해당 월 수강료 확인 → 체크 후 결제</strong><img class="g-img" src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/parent-step-74.png" alt="교육비 납부하기 화면"></li></ol><div class="g-note alert"><b>반드시 학부모 계정에서 결제해 주세요</b>학생 계정으로는 수강료 결제를 진행하지 않습니다.</div><div class="g-note"><b>현장 카드 결제도 가능해요</b>학원 운영시간 내 방문하시면 카드로도 결제하실 수 있어요.</div></div><div class="g-sec" data-tab="parent"><h2><span class="n">03</span>반교재 구매</h2><p>학부모·학생 계정 모두 구매할 수 있어요.</p><ol class="g-steps"><li><strong>홈페이지 로그인</strong></li><li><strong>메인 화면에서 ''반교재'' 선택</strong></li><li><strong>학생의 반 선택 → 교재 목록 확인 → 구매</strong><img class="g-img" src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/parent-step-75.png" alt="반교재 구매 화면"></li></ol><div class="g-note"><b>반 배정 전에는 목록이 안 보일 수 있어요</b>반 배정이 끝났는데도 교재 목록이 안 보이면 학원으로 연락해 주세요.</div></div><div class="g-sketchwrap" data-tab="parent"><div class="g-grouphead"><span class="g-group">휴대폰에 설치할 앱</span></div><div class="g-sec"><h2><span class="n">04</span>Q앱 · 시험과 재시험 관리</h2><p>학생의 학습 현황을 확인하고 관리하는 앱이에요. 신입생 학부모님은 모두 설치해 주세요.</p><ul class="g-pills"><li>시험 점수 확인</li><li>단어시험 결과</li><li>문법·문인시 등 평가 결과</li><li>재시험 일정 확인</li><li>재시험 예약</li><li>CORN 확인</li></ul><div class="g-appshots"><div class="g-appshot"><img class="g-img" src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/qapp-home.png" alt="Q앱 홈—학기 누적 단어 인증 현황"><div class="cap">시험 결과 확인</div></div><div class="g-appshot"><img class="g-img" src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/qapp-calendar.png" alt="Q앱 일정—재시험 예약 캘린더"><div class="cap">재시험 일정 · 원하는 시간 예약</div></div></div><div class="g-storebtns"><a href="https://apps.apple.com/kr/app/%EC%98%90%EB%A1%9C%EC%9A%B0%EB%B2%84%EC%8A%A4/id6748720643" target="_blank" rel="noopener" class="g-link">아이폰 설치</a><a href="https://play.google.com/store/apps/details?id=kr.co.reverselab.yellowbus.customer.yellowbus" target="_blank" rel="noopener" class="g-link">안드로이드 설치</a></div><div class="g-note"><b>CORN이란?</b>학원생활과 학습을 통해 모이는 포인트예요. Q앱에서 모은 양을 확인할 수 있고, 학원에서 열리는 행사때 사용할 수 있어요.</div></div></div><div class="g-sec" data-tab="parent"><h2><span class="n">05</span>옐로우버스 이용 안내</h2><p>셔틀을 이용하는 학생의 학부모님은 옐로우버스 앱도 함께 설치해 주세요. 학원에 등록된 학부모님은 별도 회원가입 없이 바로 이용하실 수 있어요.</p><img class="g-img" src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/yellowbus-guide.webp" alt="옐로우버스 이용 안내 — 시작하기, 스케줄 확인, 안타요 처리"><ol class="g-steps"><li><strong>옐로우버스 바로 시작하기</strong><small>학원에 등록된 학부모님은 별도의 회원가입 없이 이용할 수 있어요.</small></li><li><strong>탑승 스케줄 확인</strong><small>오늘 탑승 시간과 정류장을 미리 확인할 수 있어요.</small></li><li><strong>오늘 안 타면 ''안타요'' 처리</strong><small>탑승일정 메뉴에서 타요 버튼을 눌러 안타요 예약을 선택해주세요. 운행시작 60분 전까지 바꿀 수 있어요.</small></li></ol><div class="g-note"><b><span style="font-size:20px">오늘 셔틀을 타지 않는다면 꼭 "안타요" 처리를 해주세요</span></b><span style="font-family: &quot;IBM Plex Sans KR&quot;, &quot;Apple SD Gothic Neo&quot;, &quot;Malgun Gothic&quot;, system-ui, sans-serif; font-size: 15px;"><span style="font-size:13px"><span style="font-size:16px"><span style="font-family:''Apple SD Gothic Neo'',sans-serif">앱에서 해당 스케줄을 선택한 뒤 ‘안타요’를 눌러주세요. 셔틀선생님이 학생을 기다리지 않고 운행할 수 있습니다.</span></span></span></span></div></div><div class="g-sketchwrap" data-tab="parent"><div class="g-group">등록 후 연락</div><div class="g-sec"><h2><span class="n">06</span>신입생 안내전화가 예정되어 있습니다</h2><p>등록 후 담임 선생님이, 셔틀을 이용하는 경우 셔틀 선생님도 함께 안내전화를 드려요.</p><div class="g-subgroup"><h4>담임 선생님</h4><ul><li>수업 방식</li><li>온라인 과제</li><li>오프라인 과제</li><li>준비물</li><li>단어시험</li><li>Self-test</li><li>학생 학습 방법</li></ul></div><div class="g-subgroup"><h4>셔틀 선생님</h4><ul><li>탑승 정류장</li><li>탑승 시간</li><li>승·하차 안내</li></ul></div></div></div><div class="g-closing" data-tab="parent"><h2>처음엔 낯설어도 괜찮아요</h2><p>온라인 과제, 시험, STaRT Room 이용도 몇 번 해보면 금방 익숙해져요.모르는 게 있으면 혼자 고민하지 말고 담임 선생님이나 학원에 편하게 물어봐 주세요.</p><span class="welcome">서수원 JLS에서의 새로운 시작을 환영합니다!</span><div class="chars"><div class="char" style="background:#F2A8C4"><span class="eyes"><i></i><i></i></span></div><div class="char" style="background:#F5E29A;width:52px;height:64px"><span class="eyes" style="top:36%"><i></i><i></i></span></div><div class="char" style="background:#C9B8E8"><span class="eyes"><i></i><i></i></span></div><div class="char spiky" style="background:#F0935A"><span class="eyes" style="top:50%"><i></i><i></i></span></div></div></div><p data-tab="parent" style="text-align:center;color:#8A9BC9;font-size:13px;margin-top:10px">서수원 정상어학원 · 운영시간 (오후 1시 ~ 오후 10시)</p><div class="g-flow" data-tab="student"><h2><span style="font-size:28px">학생 한눈에 보기</span></h2><ul class="chips"><li><b>온라인 과제</b></li><li><b>준비물 확인</b></li><li><b>단어 암기</b></li><li><b>Self-test</b></li><li><b>수업</b></li><li><b>시험</b></li></ul></div><div class="g-sketchwrap" data-tab="student"><div class="g-group">수업 전에 할 일</div></div><div class="g-sec" data-tab="student"><h2><span class="n">01</span>온라인 과제는 ''다음 수업 예습''이에요</h2><p>수업이 끝난 뒤 바로, 다음 수업을 준비하는 과정이 온라인 과제예요. 수업 직전에 몰아서 하지 말고 미리 해두세요.</p><ol class="g-steps"><li><strong>학생 아이디로 로그인 → MY TREE</strong><small>정상어학원 홈페이지에 학생 계정으로 로그인한 뒤 <span style="font-weight:800">MY TREE</span>를 눌러주세요. 학부모 계정이 아닌&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style="font-weight:800">학생 계정</span>으로 해야 해요.</small><img class="g-img" src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/homepage-main.webp" alt="정상어학원 홈페이지 — MY JLS 아이콘"></li><li><strong>My Lessons에서 다음 수업 날짜 선택</strong><small>달력에서 <span style="font-weight:800">다음 수업 날짜</span>를 눌러주세요.</small><img class="g-img" src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/mylessons-list.png" alt="My Lessons 과제 목록과 달력"></li><li><strong>과제를 순서대로 완료하기</strong><small>끝난 과제에는 <span style="font-weight:800">DONE</span>이 표시돼요. 전부 DONE이 되도록 완료해주세요.</small><img class="g-img" src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/mylessons-done.png" alt="완료한 과제에 DONE 표시"></li><li><strong>오프라인 과제는 Self-Check</strong><small>화면에 있는 오프라인 과제를 실제로 끝냈다면 Self-Check도 꼭 함께 해주세요.</small></li></ol></div><div class="g-sec" data-tab="student"><h2><span class="n">02</span>과제는 언제 하나요?</h2><p><b>학원에 오기 전에</b> 끝나 있어야 해요. 수업 직전에 급하게 하기보다 미리 해두세요. 분홍색이 수업 있는 날이에요.</p><div class="g-schedule-title">화·목반 예시</div><div class="g-schedule"><div class="day-head">월</div><div class="day-head">화</div><div class="day-head">수</div><div class="day-head">목</div><div class="day-head">금</div><div class="day-cell">화요일 과제 진행</div><div class="day-cell on">수업<br>하원 후 수요일 과제 진행</div><div class="day-cell">목요일 과제 진행</div><div class="day-cell on">수업<br>하원 후 금요일 과제 진행</div><div class="day-cell">월요일 과제 진행</div></div><div class="g-schedule-title">월·수·금반 예시</div><div class="g-schedule"><div class="day-head">월</div><div class="day-head">화</div><div class="day-head">수</div><div class="day-head">목</div><div class="day-head">금</div><div class="day-cell on">수업<br>하원 후 화요일 과제 진행</div><div class="day-cell">수요일 과제 진행</div><div class="day-cell on">수업<br>하원 후 목요일 과제 진행</div><div class="day-cell">금요일 과제 진행</div><div class="day-cell on">수업<br>하원 후 월요일 과제 진행</div></div></div><div class="g-sec" data-tab="student"><h2><span class="n">03</span>중등은 숙제에도 순서가 있어요</h2><ul class="g-flowchips"><li><b>단어 암기 먼저</b></li><li><b>독해·문법 등 다른 과제</b></li></ul><p>단어를 먼저 익히면 문장 뜻이 쉽게 이해되고, 문제 푸는 시간도 줄어들어요. 다른 숙제를 먼저 하고 남는 시간에 단어를 외우는 것보다 훨씬 효율적이에요.</p></div><div class="g-sec" data-tab="student"><h2><span class="n">04</span>준비물</h2><p>준비물은 담임 선생님이 알림장이나 과제 안내에 올려주십니다. 온라인 과제를 확인할 때 그날 준비물도 함께 확인하세요.</p><h3>기본 준비물</h3><ul class="g-grid2 mint"><li>연필 또는 샤프</li><li>지우개</li><li>빨간 펜</li><li>형광펜</li><li>테이프 또는 풀</li><li>당일 수업 교재</li><li>영어학원 전용 공책</li></ul><div class="g-note">알림장이나 과제에 올라온 안내가 기본 준비물보다 우선입니다.</div></div><div class="g-sketchwrap" data-tab="student"><div class="g-group">단어 공부</div></div><div class="g-sec" data-tab="student"><h2><span class="n">05</span>온라인 단어장</h2><p>단어는 철자만 외우기보다 <b>발음을 들으며 뜻과 함께</b> 익혀주세요.</p><div class="g-subgroup"><h4>초등 · VOCA Master</h4><ul><li>발음 듣기</li><li>단어 학습</li><li>미니 테스트</li><li>단어 게임</li></ul><div class="g-appshots"><div class="g-appshot"><img class="g-img" src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/study-words.png" alt="VOCA Master Study 화면"><div class="cap">Study · 발음 듣고 뜻 익히기</div></div><div class="g-appshot"><img class="g-img" src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/test-quiz.png" alt="VOCA Master Test 화면"><div class="cap">Test · 뜻 보고 단어 고르기</div></div></div><div class="g-storebtns"><a href="https://sirradist.github.io/JLSCHESS/" target="_blank" rel="noopener" class="g-link">VOCA Master 열기 ↗</a></div><p style="margin-top:8px;font-size:12.5px;color:#6B7BA0">&nbsp; &nbsp; 비밀번호</p><span class="g-mini g-mini-round" contenteditable="false" onclick="renameBadge(this)">jls202606</span>&nbsp;</div><div class="g-subgroup"><h4>중등 · JLS VOCA</h4><ul><li>정확한 발음 듣기</li><li>영어·한글 뜻 함께</li><li>숨기기 기능</li><li>테스트</li></ul><div class="g-appshots"><div class="g-appshot"><img class="g-img" src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/mobile-wordtrainer.png" alt="Master the Words — JLS Word Trainer"><div class="cap">Master the Words</div></div><div class="g-appshot"><img class="g-img" src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/mobile-readingwords.png" alt="JLS 활용독해 단어 — 교재별 단어장"><div class="cap">교재별 단어장</div></div></div><div class="g-storebtns"><a href="https://varonnetworkss.github.io/jls-VOCA/" target="_blank" rel="noopener" class="g-link">성과 단어장 ↗</a><a href="https://varonnetworks.github.io/jls-vocab/" target="_blank" rel="noopener" class="g-link">활용 단어장 ↗</a></div></div><div class="g-note"><b>휴대폰 홈 화면에 추가하면 앱처럼 쓸 수 있어요</b>&nbsp;아이폰: Safari로 접속 후 공유 버튼 → 홈 화면에 추가&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;갤럭시: 삼성 인터넷이나 Chrome으로 접속 후 메뉴 → 홈 화면에 추가</div></div><div class="g-sec" data-tab="student"><h2><span class="n">06</span>Self-test로 단어 확인하기</h2><p>정식 시험 전, 내가 단어를 정말 외웠는지 직접 확인하는 과정이에요. 여러 번 읽기보다 <b>보지 않고 직접 써보는 것</b>이 핵심입니다. 담임 선생님이 프린트를 주시면 그 방법을 따르고, 없으면 공책 4칸 접기로 해보세요.</p><div class="g-selftest" data-step="0" data-words="[{&quot;ko&quot;:&quot;사과&quot;,&quot;en&quot;:&quot;apple&quot;},{&quot;ko&quot;:&quot;빌리다&quot;,&quot;en&quot;:&quot;borrow&quot;},{&quot;ko&quot;:&quot;용감한&quot;,&quot;en&quot;:&quot;brave&quot;},{&quot;ko&quot;:&quot;도서관&quot;,&quot;en&quot;:&quot;library&quot;}]"><ul class="g-st-words" hidden=""><li data-ko="사과" data-en="apple"></li><li data-ko="빌리다" data-en="borrow"></li><li data-ko="용감한" data-en="brave"></li><li data-ko="도서관" data-en="library"></li></ul><h4 class="g-st-title">4칸 접기 Self-test 따라하기</h4><div class="g-st-hint"><span class="g-st-tap">👆</span> 좋아요! 한 칸 쓰고 <b>바로 채점</b>, 그다음 칸으로</div><div class="g-st-tabs"><button type="button" data-jump="0" aria-pressed="true"><i>1</i>1칸 뜻</button><button type="button" data-jump="1" aria-pressed="false"><i>2</i>2칸 영어</button><button type="button" data-jump="2" aria-pressed="false"><i>3</i>3칸 뜻</button><button type="button" data-jump="3" aria-pressed="false"><i>4</i>4칸 영어</button></div><div class="g-st-grid"><div class="g-st-col now" data-col="0"><span class="h">1 뜻</span><span class="w">사과</span><span class="w">빌리다</span><span class="w">용감한</span><span class="w">도서관</span></div><div class="g-st-col blank" data-col="1"><span class="h">2 영어</span><span class="w">apple</span><span class="w bad">borow</span><span class="fix">→ borrow</span><span class="w">brave</span><span class="w">library</span></div><div class="g-st-col blank" data-col="2"><span class="h">3 뜻</span><span class="w">사과</span><span class="w">빌리다</span><span class="w">용감한</span><span class="w">도서관</span></div><div class="g-st-col blank" data-col="3"><span class="h">4 영어</span><span class="w">apple</span><span class="w">borrow</span><span class="w">brave</span><span class="w">library</span></div></div><p class="g-st-cap">단어책을 보면서 1칸에 뜻을 적습니다. 다 적으면 단어책과 비교해 맞게 옮겼는지 채점합니다.</p><div class="g-st-nav"><button type="button" class="g-st-prev" disabled="">← 이전</button><span class="g-st-prog">1 / 4</span><button type="button" class="g-st-next">다음 칸 쓰기 →</button></div></div><a class="g-video" href="https://www.youtube.com/watch?v=nWQdc2EVb8k" target="_blank" rel="noopener"><img src="https://img.youtube.com/vi/nWQdc2EVb8k/hqdefault.jpg" alt="영어단어 암기공부법 영상 썸네일"><span class="play"></span></a><p class="g-video-cap"><a href="https://www.youtube.com/watch?v=nWQdc2EVb8k" target="_blank" rel="noopener">YouTube에서 열기 ↗</a></p><h3 style="font-family: Jua, &quot;IBM Plex Sans KR&quot;, system-ui, sans-serif; font-weight: 400; line-height: 1.3; text-wrap: balance; margin: 22px 0px 0px; font-size: 19px; color: rgb(32, 79, 161);">한 칸 쓸 때마다 바로 채점</h3><p style="margin-top:8px;font-size:13px;color:#6B7BA0"><span style="color: rgb(75, 94, 136); font-family: &quot;IBM Plex Sans KR&quot;, &quot;Apple SD Gothic Neo&quot;, &quot;Malgun Gothic&quot;, system-ui, sans-serif; font-size: 16px;"></span><span style="font-size:13px"><span style="font-family:''Apple SD Gothic Neo'',sans-serif"><span style="font-family:''Apple SD Gothic Neo'',sans-serif"><span style="color: rgb(75, 94, 136); font-family: &quot;IBM Plex Sans KR&quot;, &quot;Apple SD Gothic Neo&quot;, &quot;Malgun Gothic&quot;, system-ui, sans-serif; font-size: 16px;"></span><span style="font-family:''Apple SD Gothic Neo'',sans-serif"><span style="font-size:13px"><span style="font-size:16px"><span style="font-size:13px"><span style="font-family:''Apple SD Gothic Neo'',sans-serif"><span style="color: rgb(75, 94, 136); font-family: &quot;IBM Plex Sans KR&quot;, &quot;Apple SD Gothic Neo&quot;, &quot;Malgun Gothic&quot;, system-ui, sans-serif; font-size: 16px;">네 칸을 다 쓰고 한꺼번에 채점하지 않습니다. </span><b style="color: rgb(75, 94, 136); font-family: &quot;IBM Plex Sans KR&quot;, &quot;Apple SD Gothic Neo&quot;, &quot;Malgun Gothic&quot;, system-ui, sans-serif; font-size: 16px;">한 칸을 다 쓰면 바로 단어책과 비교해 채점</b><span style="color: rgb(75, 94, 136); font-family: &quot;IBM Plex Sans KR&quot;, &quot;Apple SD Gothic Neo&quot;, &quot;Malgun Gothic&quot;, system-ui, sans-serif; font-size: 16px;">하고, 틀린 단어는 정답만 고쳐 쓰고 넘어가지 말고 </span><b style="color: rgb(75, 94, 136); font-family: &quot;IBM Plex Sans KR&quot;, &quot;Apple SD Gothic Neo&quot;, &quot;Malgun Gothic&quot;, system-ui, sans-serif; font-size: 16px;">발음·뜻·스펠링</b><span style="color: rgb(75, 94, 136); font-family: &quot;IBM Plex Sans KR&quot;, &quot;Apple SD Gothic Neo&quot;, &quot;Malgun Gothic&quot;, system-ui, sans-serif; font-size: 16px;">을 다시 확인합니다. 앞 칸에서 틀린 단어는 </span><b style="color: rgb(75, 94, 136); font-family: &quot;IBM Plex Sans KR&quot;, &quot;Apple SD Gothic Neo&quot;, &quot;Malgun Gothic&quot;, system-ui, sans-serif; font-size: 16px;">다시 학습해서 다음 칸에서는 맞힐 수 있도록</b><span style="color: rgb(75, 94, 136); font-family: &quot;IBM Plex Sans KR&quot;, &quot;Apple SD Gothic Neo&quot;, &quot;Malgun Gothic&quot;, system-ui, sans-serif; font-size: 16px;"> 노력합니다.</span></span></span></span></span></span><span style="color: rgb(75, 94, 136); font-family: &quot;IBM Plex Sans KR&quot;, &quot;Apple SD Gothic Neo&quot;, &quot;Malgun Gothic&quot;, system-ui, sans-serif; font-size: 16px;"></span></span></span></span><span style="color: rgb(75, 94, 136); font-family: &quot;IBM Plex Sans KR&quot;, &quot;Apple SD Gothic Neo&quot;, &quot;Malgun Gothic&quot;, system-ui, sans-serif; font-size: 16px;"></span></p></div><div class="g-sketchwrap" data-tab="student"><div class="g-group">교재</div></div><div class="g-sec" data-tab="student"><h2><span class="n">07</span>초등 교재 한눈에 보기</h2><table class="g-mini-table"><tbody><tr class="g-mt-head"><td>교재</td><td>주기</td><td>시작 시기</td></tr><tr><td>CHESS Book</td><td>한 달에 1권</td><td><br></td></tr><tr><td>Story Book</td><td>2주에 1권</td><td><br></td></tr><tr><td>Speaking Tree</td><td>3개월 내내</td><td>DSC1부터</td></tr><tr><td>Writing Portfolio</td><td>3개월 내내</td><td>DSD부터</td></tr><tr><td>문법 교재</td><td>3개월 내내</td><td><br></td></tr></tbody></table></div><div class="g-sec" data-tab="student"><h2><span class="n">08</span>교재 사용 습관</h2><ul class="g-list-ast"><li>교재 앞에 이름 적기</li><li>시험지·프린트는 정해진 위치에 붙이기</li><li>채점은 빨간 펜으로</li><li>틀린 문제는 바르게 고쳐 쓰기</li><li>선생님 첨삭 확인하기</li><li>결석한 날도 과제 확인하기</li></ul><img class="g-poster" src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/book-habits-poster.webp" alt="수업교재 이렇게 해볼까요 — 교재 관리와 채점 관리 포스터"><p class="g-poster-cap">수업교재 이렇게 해볼까요? · 교재 관리와 채점 관리</p><a class="g-linkbtn" href="#">THE BEST BOOK 좋은 예시 보러가기 →</a><p style="margin-top:8px;font-size:13px;color:#6B7BA0">시험지 붙이는 위치나 교재 활용법은 레벨마다 다를 수 있어요. 담임 선생님 안내를 따라주세요.</p></div><div class="g-closing" data-tab="student"><h2>처음엔 낯설어도 괜찮아요</h2><p>온라인 과제, 시험, STaRT Room 이용도 몇 번 해보면 금방 익숙해져요.모르는 게 있으면 혼자 고민하지 말고 담임 선생님이나 학원에 편하게 물어봐 주세요.</p><span class="welcome">서수원 JLS에서의 새로운 시작을 환영합니다!</span><div class="chars"><div class="char" style="background:#F2A8C4"><span class="eyes"><i></i><i></i></span></div><div class="char" style="background:#F5E29A;width:52px;height:64px"><span class="eyes" style="top:36%"><i></i><i></i></span></div><div class="char" style="background:#C9B8E8"><span class="eyes"><i></i><i></i></span></div><div class="char spiky" style="background:#F0935A"><span class="eyes" style="top:50%"><i></i><i></i></span></div></div></div><p data-tab="student" style="text-align:center;color:#8A9BC9;font-size:13px;margin-top:10px">서수원 정상어학원 · 운영시간 (오후 1시 ~ 오후 10시)</p><div class="g-flow" data-tab="exam"><h2><span style="font-size:28px">시험 한눈에 보기</span></h2><ul class="chips"><li><b>시험</b></li><li><b>통과 못 하면</b></li><li><b>범위 전체 다시 공부</b></li><li><b>공부 흔적 확인</b></li><li><b>재시험</b></li><li><b>시험지 돌려받기</b></li></ul></div><div class="g-sketchwrap" data-tab="exam"><div class="g-group">시험 종류와 기준</div></div><div class="g-sec" data-tab="exam"><h2><span class="n">01</span>어떤 시험을 보나요?</h2><p>초등·중등, 그리고 레벨에 따라 다릅니다.</p><table class="g-mini-table"><tbody><tr class="g-mt-head"><td>구분</td><td>시험</td><td>횟수</td><td>첫 시험 통과</td><td>재시험 통과</td></tr><tr><td>초등 DSB</td><td><b>단어시험</b></td><td>주 1회</td><td>90% 이상</td><td>100%<span class="g-mt-badge">만점</span></td></tr><tr><td rowspan="3">초등 DSC 이상</td><td><b>단어시험</b></td><td>주 1회</td><td>90% 이상</td><td>100%<span class="g-mt-badge">만점</span></td></tr><tr><td><b>CHAT</b></td><td>-</td><td>90점</td><td>90점</td></tr><tr><td><b>문인시</b></td><td>-</td><td>90점</td><td>90점</td></tr><tr><td rowspan="2">중등</td><td><b>단어시험</b></td><td>등원할 때마다</td><td>90% 이상</td><td>100%<span class="g-mt-badge">만점</span></td></tr><tr><td><b>문인시</b></td><td>-</td><td>90점</td><td>90점</td></tr></tbody></table><p style="margin-top:8px;font-size:13px;color:#6B7BA0">단어시험은 DSB부터 시작하며, 시험 단어 개수는 레벨마다 달라요. 시험 결과와 재시험 일정은 Q앱에서 확인할 수 있어요.</p></div><div class="g-sketchwrap" data-tab="exam"><div class="g-group">통과하지 못했다면</div></div><div class="g-sec" data-tab="exam"><h2><span class="n">02</span>CHAT·문인시 80점 미만이면 보강 먼저</h2><ul class="g-flowchips"><li><b>첫 시험 80점 미만</b></li><li><b>보강</b></li><li><b>재시험</b></li></ul><p>바로 재시험을 보지 않고 보강을 먼저 받아요. 이 규칙은 <b>CHAT와 문인시에만</b> 적용되고, 단어시험은 점수와 관계없이 해당되지 않아요.</p></div><div class="g-sec" data-tab="exam"><h2><span class="n">03</span>단어 재시험은 만점이어야 통과</h2><p>재시험은 틀린 단어 몇 개만 외워 오는 과정이 아니라, <b>시험 범위 전체를 다시 확인하는 과정</b>이기 때문이에요.</p><h3>그래서 시험지를 바로 돌려주지 않아요</h3><p>통과하지 못한 단어시험지는 재시험을 보기 전까지 학원에서 보관해요. 시험지를 먼저 돌려주면 틀린 단어만 골라 외워 오는 경우가 많고, 그러면 처음에 맞았던 단어를 재시험에서 다시 틀리게 돼요. 재시험 준비는 범위 전체로 해주세요.</p></div><div class="g-sketchwrap" data-tab="exam"><div class="g-group">재시험 준비와 응시</div></div><div class="g-sec" data-tab="exam"><h2><span class="n">04</span>공부한 흔적을 먼저 보여주세요</h2><div class="g-note warn"><b><span class="ex">!</span>재시험은 바로 볼 수 없어요</b>재시험·예비시험은 공부한 것을 먼저 확인받은 뒤에 시험지를 받을 수 있어요.</div><h4>확인받을 것 (택1)</h4><ul class="g-grid2 mint"><li>공책 4칸 Self-test</li><li>담임선생님 프린트</li><li>별도 학습자료</li><li>오답 정리</li></ul><h4>문인시 재시험은 준비 방법이 달라요</h4><ul class="g-flowchips"><li><b>학습자료 풀기<span class="g-badge-dot">clue 표시!</span></b></li><li><b>채점</b></li><li><b>틀린 문제 확인</b></li><li><b>오답 정리</b></li><li><b>재시험</b></li></ul><p>담임선생님이 준 학습자료로 준비해요. 문제를 풀 때는 <b class="g-red">답의 근거(clue)를 꼭 표시</b>하세요.</p></div><div class="g-sec" data-tab="exam"><h2><span class="n">05</span>재시험은 STaRT Room에서</h2><p><span style="font-size:13px"><span style="font-size:16px"><span style="font-size:20px"><span style="font-size:16px"><span style="font-size:16px"><span style="font-size:13px"><span style="font-size:13px"><span style="font-size:16px">재시험과 중등 예비시험은 STaRT Room에서 봐요. 입실 방법은 아래 STaRT Room 안내를 확인하세요.</span></span></span></span></span></span></span></span></p><div class="g-timebox"><span class="num">15''</span><div class="body"><b>수업 시작·버스 탑승 15분 전까지</b><p>예비시험과 재시험은 이때까지만 응시할 수 있어요. 문인시는 이 규칙에서 제외돼요.</p></div></div><ul class="g-list-ast"><li>시험과 예비시험 채점은 <span style="font-weight:800">지정된 자리</span>에서만 해요.</li><li>예비시험지, 문인시 시험지, 답안지 등 시험 자료는 교실 밖으로 가져가지 않아요.</li></ul></div><div class="g-sketchwrap" data-tab="exam"><div class="g-group">통과 후</div></div><div class="g-sec" data-tab="exam"><h2><span class="n">06</span>통과한 시험지는 교재에 붙이기</h2><p>본시험이든 재시험이든, <b>통과한 시험지는 모두 교재에 붙여요.</b> 붙이는 위치도 같아요.</p><ol class="g-steps"><li><strong>본시험에 통과했다면</strong><small>시험지를 돌려받아 교재의 정해진 위치에 붙여요.</small></li><li><strong>재시험에 통과했다면</strong><small>그동안 보관하던 본시험지와 재시험지를 모두 돌려받아 함께 붙여요.</small></li><li><strong>정해진 위치에 붙이기</strong><small>아무 곳에나 끼워두지 말고 담임 선생님이 안내한 위치에 정리해요.</small></li></ol><h4>어디에 붙이나요?</h4><h3>초등 CHESS</h3><ul class="g-grid2"><li>단어 시험지 — 각 Lesson 페이지의 오른쪽</li><li>CHAT 시험지 — 교재 맨 뒤 페이지부터 앞쪽으로, 오른쪽 페이지에 차례대로</li></ul><div class="g-carousel"><div class="g-carousel-track"><div class="g-carousel-item"><img src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/exam-chess-word.webp" alt="CHESS 단어 시험지 — Lesson 페이지 오른쪽에 붙인 모습"><div class="cap">단어 시험지 · Lesson 페이지 오른쪽</div></div><div class="g-carousel-item"><img src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/exam-chess-chat.webp" alt="CHESS CHAT 시험지 — 교재 맨 뒤에서부터 붙인 모습"><div class="cap">CHAT 시험지 · 맨 뒤에서부터 오른쪽</div></div></div><div class="g-carousel-dots"></div></div><h3>중등 ACE</h3><ul class="g-grid2"><li>T-map·R-map — 해당 Chapter 페이지의 오른쪽</li><li>절대수능맵 독해 — 해당 Unit 페이지의 오른쪽</li><li>활용 독해 단어 — Chapter 페이지 뒤, Unit 페이지의 오른쪽 (범위가 두 곳에 걸치면 앞 범위 기준)</li></ul><div class="g-carousel"><div class="g-carousel-track"><div class="g-carousel-item"><img src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/exam-ace-tmap.webp" alt="ACE T-map·R-map 시험지 — Chapter 페이지 오른쪽에 붙인 모습"><div class="cap">T-map·R-map · Chapter 오른쪽</div></div><div class="g-carousel-item"><img src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/exam-ace-reading.webp" alt="ACE 절대수능맵 독해 시험지 — Unit 페이지 오른쪽에 붙인 모습"><div class="cap">절대수능맵 독해 · Unit 오른쪽</div></div><div class="g-carousel-item"><img src="https://hplndiuoohantbalixwu.supabase.co/storage/v1/object/public/guide-images/seosuwonjls/exam-ace-words.webp" alt="ACE 활용 독해 단어 시험지 — Chapter 뒤 Unit 페이지 오른쪽에 붙인 모습"><div class="cap">활용 독해 단어 · Chapter 뒤 Unit 오른쪽</div></div></div><div class="g-carousel-dots"></div></div></div><div class="g-sketchwrap" data-tab="exam"><div class="g-group">STaRT Room</div></div><div class="g-sec" data-tab="exam"><h2><span class="n">07</span>STaRT Room이란?</h2><p><b>Study Together and Run Together.</b> 혼자 자습하거나, 재시험·중등 예비시험을 보거나, 필요한 학습을 하는 공간이에요.</p><div class="g-infogrid"><div class="g-infocard"><b>자습</b><p>일찍 도착했거나 혼자 공부할 공간이 필요할 때</p></div><div class="g-infocard"><b>재시험</b><p>단어, CHAT, 문인시 등</p></div><div class="g-infocard"><b>중등 예비시험</b><p>본 시험 전 예비시험 응시</p></div></div></div><div class="g-sec" data-tab="exam"><h2><span class="n">08</span>입실 방법</h2><p style="margin-top:8px;font-size:13px;color:#6B7BA0">(사진은 서수원 실제 모습으로 나중에 넣어주세요)</p><ol class="g-steps"><li><strong>패드에서 입실체크</strong><small>패드에서 입실을 누르고 뒷번호 4자리를 입력하면 자리가 자동으로 배정돼요. 나갈 때는 퇴실, 잠깐 나갔다 올 때는 외출·복귀를 눌러요.</small></li><li><strong>이용 목적 확인</strong><small>자습, 재시험, 예비시험 중 오늘 온 목적에 맞게 이용해요.</small></li><li><strong>휴대폰 제출</strong><small>지정된 보관 장소에 제출해요. 온라인 과제 확인이나 온라인 단어장 이용 등 학습에 필요할 때는 안내에 따라 사용할 수 있어요.</small></li></ol><p style="margin-top:8px;font-size:13px;color:#6B7BA0">이 분원의 입실 방식이 패드가 아니거나 다른 점이 있으면 이 부분을 고쳐주세요.</p></div><div class="g-sec" data-tab="exam"><h2><span class="n">09</span>이용 규칙</h2><ul class="g-list-ast"><li>재시험·예비시험은 공부한 흔적을 먼저 확인받은 뒤 응시해요. 자세한 내용은 위의 ''공부한 흔적을 먼저 보여주세요''를 확인하세요.</li><li>시험은 지정된 자리에서만 보고, 시험 자료는 교실 밖으로 가져가지 않아요.</li><li>식사를 못 했다면 선생님께 허락을 받고 교실 밖에서 먹어주세요.</li></ul></div><div class="g-closing" data-tab="exam"><h2>처음엔 낯설어도 괜찮아요</h2><p>온라인 과제, 시험, STaRT Room 이용도 몇 번 해보면 금방 익숙해져요.모르는 게 있으면 혼자 고민하지 말고 담임 선생님이나 학원에 편하게 물어봐 주세요.</p><span class="welcome">서수원 JLS에서의 새로운 시작을 환영합니다!</span><div class="chars"><div class="char" style="background:#F2A8C4"><span class="eyes"><i></i><i></i></span></div><div class="char" style="background:#F5E29A;width:52px;height:64px"><span class="eyes" style="top:36%"><i></i><i></i></span></div><div class="char" style="background:#C9B8E8"><span class="eyes"><i></i><i></i></span></div><div class="char spiky" style="background:#F0935A"><span class="eyes" style="top:50%"><i></i><i></i></span></div></div></div><p data-tab="exam" style="text-align:center;color:#8A9BC9;font-size:13px;margin-top:10px">서수원 정상어학원 · 운영시간 (오후 1시 ~ 오후 10시)</p><div class="g-flow" data-tab="life"><h2>학원 생활</h2><ul class="chips"><li><b>공지사항</b></li><li><b>방학 특강</b></li><li><b>학기말 시상</b></li></ul></div><div class="g-sec" data-tab="life"><h2><span class="n">01</span>공지와 학사일정</h2><p>학원 소식과 일정은 아래에서 확인하실 수 있어요.</p><p style="font-size:13px;color:#6B7BA0">(여기에 분원 블로그·홈페이지 링크를 넣어주세요)</p></div><div class="g-sec" data-tab="life"><h2><span class="n">02</span>방학 특강</h2><p>여름·겨울방학마다 커리큘럼에 맞춘 특강이 진행돼요. (분원 특강 일정·대상 레벨을 적어주세요)</p></div><div class="g-sec" data-tab="life"><h2><span class="n">03</span>학기말 시상</h2><p>매 학기를 마무리하며 한 학기 동안의 노력과 성장을 시상해요.</p><ul class="g-grid2"><li>THE BEST SCORE</li><li>THE BEST SPEAKER</li><li>THE BEST BOOK</li></ul></div><div class="g-closing" data-tab="life"><h2>처음엔 낯설어도 괜찮아요</h2><p>온라인 과제, 시험, STaRT Room 이용도 몇 번 해보면 금방 익숙해져요.모르는 게 있으면 혼자 고민하지 말고 담임 선생님이나 학원에 편하게 물어봐 주세요.</p><span class="welcome">서수원 JLS에서의 새로운 시작을 환영합니다!</span><div class="chars"><div class="char" style="background:#F2A8C4"><span class="eyes"><i></i><i></i></span></div><div class="char" style="background:#F5E29A;width:52px;height:64px"><span class="eyes" style="top:36%"><i></i><i></i></span></div><div class="char" style="background:#C9B8E8"><span class="eyes"><i></i><i></i></span></div><div class="char spiky" style="background:#F0935A"><span class="eyes" style="top:50%"><i></i><i></i></span></div></div></div><p data-tab="life" style="text-align:center;color:#8A9BC9;font-size:13px;margin-top:10px">서수원 정상어학원 · 운영시간 (오후 1시 ~ 오후 10시)</p>', updated_at = now(), updated_by = 'claude-session'
where branch_id = 'seosuwonjls';

